52	/**
53	 * @author Vitaliy Fedoriv
54	 */
55	
56	@RestController
57	@CrossOrigin(exposedHeaders = "errors, content-type")
58	@RequestMapping("/api")
59	public class OwnerRestControllerV1 implements OwnersApi {
60	
61	    private final ClinicService clinicService;
62	
63	    private final OwnerMapper ownerMapper;
64	
65	    private final PetMapper petMapper;
66	
67	    private final VisitMapper visitMapper;
68	
69	    private final TelephoneNormalizer telephoneNormalizer;
70	
71	    public OwnerRestControllerV1(ClinicService clinicService,
72	                                 OwnerMapper ownerMapper,
73	                                 PetMapper petMapper,
74	                                 VisitMapper visitMapper,
75	                                 TelephoneNormalizer telephoneNormalizer) {
76	        this.clinicService = clinicService;
77	        this.ownerMapper = ownerMapper;
78	        this.petMapper = petMapper;
79	        this.visitMapper = visitMapper;
80	        this.telephoneNormalizer = telephoneNormalizer;
81	    }
82	
83	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
84	    @Override
85	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
86	        Collection<Owner> owners;
87	        if (lastName != null) {
88	            owners = this.clinicService.findOwnerByLastName(lastName);
89	        } else {
90	            owners = this.clinicService.findAllOwners();
91	        }
92	        if (owners.isEmpty()) {
93	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
94	        }
95	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
96	    }
97	
98	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
99	    @Override
100	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
101	        Owner owner = this.clinicService.findOwnerById(ownerId);
102	        if (owner == null) {
103	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
104	        }
105	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
106	    }
107	
108	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
109	    @Override
110	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
111	        normalizeAndValidate(ownerFieldsDto);
112	        HttpHeaders headers = new HttpHeaders();
113	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
114	        owner.setCustomerCode(generateCustomerCode(owner.getLastName()));
115	        this.clinicService.saveOwner(owner);
116	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
117	        headers.setLocation(UriComponentsBuilder.newInstance()
118	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
119	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
120	    }
121	
122	    /**
123	     * Prepares a new owner's payload for persistence, applying every rule an incoming owner must satisfy before it is
124	     * saved. Required fields are checked first; the telephone is then normalized to its canonical stored form, written
125	     * back onto the payload and rejected if another owner already uses it; the email is canonicalized; and a missing
126	     * registration date defaults to the current date. The payload is mutated in place so the caller can map and save it
127	     * directly.
128	     *
129	     * @param ownerFieldsDto the incoming owner payload, mutated in place
130	     * @throws MissingOwnerFieldsException if any required field is missing or blank
131	     * @throws DuplicateTelephoneException if another owner already uses the normalized telephone
132	     */
133	    private void normalizeAndValidate(OwnerFieldsDto ownerFieldsDto) {
134	        validateRequiredFields(ownerFieldsDto);
135	        String telephone = telephoneNormalizer.normalize(ownerFieldsDto.getTelephone());
136	        ownerFieldsDto.setTelephone(telephone);
137	        requireUniqueTelephone(telephone);
138	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
139	        if (ownerFieldsDto.getRegistrationDate() == null) {
140	            ownerFieldsDto.setRegistrationDate(LocalDate.now());
141	        }
142	    }
143	
144	    /**
145	     * Builds an owner's {@code customerCode}, formatted {@code <LAST3>-<NNNN>}. {@code LAST3} is the upper-cased first
146	     * three letters of the last name and {@code NNNN} is a global 4-digit zero-padded sequence equal to one more than
147	     * the current number of owners (e.g. {@code SMI-0007}).
148	     *
149	     * @param lastName the owner's last name
150	     * @return the generated customer code
151	     */
152	    private String generateCustomerCode(String lastName) {
153	        String prefix = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase();
154	        int sequence = this.clinicService.findAllOwners().size() + 1;
155	        return String.format("%s-%04d", prefix, sequence);
156	    }
157	
158	    /**
159	     * Rejects an owner payload that omits or leaves blank any required field. Bean Validation already rejects missing
160	     * ({@code null}) required fields, but permits values that are blank (empty or whitespace-only) for fields without a
161	     * stricter pattern, so this check enforces the "missing or blank" rule uniformly across every required field.
162	     *
163	     * @param ownerFieldsDto the owner payload to validate
164	     * @throws MissingOwnerFieldsException if any of firstName, lastName, address, city or telephone is missing or blank
165	     */
166	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
167	        List<String> missingFields = new ArrayList<>();
168	        requireText(missingFields, "firstName", ownerFieldsDto.getFirstName());
169	        requireText(missingFields, "lastName", ownerFieldsDto.getLastName());
170	        requireText(missingFields, "address", ownerFieldsDto.getAddress());
171	        requireText(missingFields, "city", ownerFieldsDto.getCity());
172	        requireText(missingFields, "telephone", ownerFieldsDto.getTelephone());
173	        if (!missingFields.isEmpty()) {
174	            throw new MissingOwnerFieldsException(missingFields);
175	        }
176	    }
177	
178	    private void requireText(List<String> missingFields, String fieldName, String value) {
179	        if (value == null || value.isBlank()) {
180	            missingFields.add(fieldName);
181	        }
182	    }
183	
184	    /**
185	     * Normalizes an optional owner email. A syntactically valid address is already enforced by Bean Validation on the
186	     * request payload, so this only canonicalizes the value that gets stored and returned by lower-casing it. A missing
187	     * (blank or {@code null}) email is left untouched, since the field is optional.
188	     *
189	     * @param email the raw email value from the request, may be {@code null}
190	     * @return the lower-cased email, or the original value when none was supplied
191	     */
192	    private String normalizeEmail(String email) {
193	        if (email == null || email.isBlank()) {
194	            return email;
195	        }
196	        return email.toLowerCase();
197	    }
198	
199	    /**
200	     * Rejects creating an owner whose normalized telephone is already used by another owner. Existing owners' stored
201	     * telephones are canonicalized the same way before comparison, so the rule holds regardless of how their number was
202	     * originally formatted.
203	     *
204	     * @param telephone the normalized telephone of the owner being created
205	     * @throws DuplicateTelephoneException if any existing owner already uses the same normalized telephone
206	     */
207	    private void requireUniqueTelephone(String telephone) {
208	        boolean inUse = this.clinicService.findAllOwners().stream()
209	            .map(existing -> telephoneNormalizer.canonicalize(existing.getTelephone()))
210	            .anyMatch(telephone::equals);
211	        if (inUse) {
212	            throw new DuplicateTelephoneException("telephone is already in use by another owner");
213	        }
214	    }
