216	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
217	    @Override
218	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
219	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
220	        if (currentOwner == null) {
221	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
222	        }
223	        currentOwner.setAddress(ownerFieldsDto.getAddress());
224	        currentOwner.setCity(ownerFieldsDto.getCity());
225	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
226	        currentOwner.setLastName(ownerFieldsDto.getLastName());
227	        currentOwner.setTelephone(ownerFieldsDto.getTelephone());
228	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
229	        this.clinicService.saveOwner(currentOwner);
230	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
231	    }
232	
233	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
234	    @Transactional
235	    @Override
236	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
237	        Owner owner = this.clinicService.findOwnerById(ownerId);
238	        if (owner == null) {
239	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
240	        }
241	        this.clinicService.deleteOwner(owner);
242	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
243	    }
244	
245	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
246	    @Override
247	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
248	        Owner owner = this.clinicService.findOwnerById(ownerId);
249	        if (owner == null) {
250	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
251	        }
252	        HttpHeaders headers = new HttpHeaders();
253	        Pet pet = petMapper.toPet(petFieldsDto);
254	        owner.setId(ownerId);
255	        pet.setOwner(owner);
256	        pet.getType().setName(null);
257	        this.clinicService.savePet(pet);
258	        PetDto petDto = petMapper.toPetDto(pet);
259	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
260	            .buildAndExpand(pet.getId()).toUri());
261	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
262	    }
263	
264	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
265	    @Override
266	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
267	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
268	        if (currentOwner != null) {
269	            Pet currentPet = this.clinicService.findPetById(petId);
270	            if (currentPet != null) {
271	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
272	                currentPet.setName(petFieldsDto.getName());
273	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
274	                this.clinicService.savePet(currentPet);
275	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
276	            }
277	        }
278	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
279	    }
280	
281	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
282	    @Override
283	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
284	        HttpHeaders headers = new HttpHeaders();
285	        Visit visit = visitMapper.toVisit(visitFieldsDto);
286	        Pet pet = new Pet();
287	        pet.setId(petId);
288	        visit.setPet(pet);
289	        this.clinicService.saveVisit(visit);
290	        VisitDto visitDto = visitMapper.toVisitDto(visit);
291	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
292	            .buildAndExpand(visit.getId()).toUri());
293	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
294	    }
295	
296	
297	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
298	    @Override
299	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
300	        Owner owner = this.clinicService.findOwnerById(ownerId);
301	        if (owner != null) {
302	            Pet pet = owner.getPet(petId);
303	            if (pet != null) {
304	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
305	            }
306	        }
307	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
308	    }
309	}
